CREATE OR REPLACE FUNCTION public.reject_kiosk_audit_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $function$ BEGIN
IF TG_OP='DELETE' AND current_user IN ('postgres','service_role','supabase_admin') AND OLD.id IN ('268f32bf-97b5-4874-ab91-4fa37eef9535'::uuid,'331d13b3-25b7-4365-938b-47fb58e3d530'::uuid,'379426b5-54cb-4aa7-ad8f-253715ad18fa'::uuid,'4f1a2db1-9aae-41a5-9974-21d4ece07485'::uuid,'510b3011-f52a-458d-9903-e3ae9265125b'::uuid,'52a61873-9344-46d1-abcc-da29ea0c34fa'::uuid,'6c1fa143-13e8-4c50-9c27-968d68f874d9'::uuid,'b0ba5427-0973-49a9-aa85-2dbd471c62b3'::uuid,'b3b9be17-af9d-4495-9b90-b021b0ccf433'::uuid,'b9450473-9dc9-4ca7-9d39-47b29e99e9e5'::uuid,'e2b25f2c-d0dd-4879-8e6f-e8e58f370704'::uuid) THEN RETURN OLD; END IF;
RAISE EXCEPTION 'Journal des bornes immuable'; END $function$;